		NavigationServer2D.BakeFromSourceGeometryData(newNavigationMesh, new NavigationMeshSourceGeometryData2D());
		GetNode<NavigationRegion2D>("NavigationRegion2D").NavigationPolygon = newNavigationMesh;


		Adding vertices and polygon indices manually.


		var new_navigation_mesh = NavigationPolygon.new()
		var new_vertices = PackedVector2Array()
		new_navigation_mesh.vertices = new_vertices
		var new_polygon_indices = PackedInt32Array()
		new_navigation_mesh.add_polygon(new_polygon_indices)
		$NavigationRegion2D.navigation_polygon = new_navigation_mesh


		var newNavigationMesh = new NavigationPolygon();
		Vector2[] newVertices = ;
		newNavigationMesh.Vertices = newVertices;
		int[] newPolygonIndices = ;
		newNavigationMesh.AddPolygon(newPolygonIndices);
		GetNode<NavigationRegion2D>("NavigationRegion2D").NavigationPolygon = newNavigationMesh;

_get_configuration_warnings.description:
The elements in the array returned from this method are displayed as warnings in the Scene dock if the script that overrides it is a tool script.
				Returning an empty array produces no warnings.
				Call update_configuration_warnings when the warnings need to be updated for this node.

				@export var energy = 0:
					set(value):
						energy = value
						update_configuration_warnings()

				func _get_configuration_warnings():
					if energy < 0:
						return ["Energy must be 0 or greater."]
					else:
						return []

add_child.description:
Adds a child node. Nodes can have any number of children, but every child must have a unique name. Child nodes are automatically deleted when the parent node is deleted, so an entire scene can be removed by deleting its topmost node.
				If force_readable_name is true, improves the readability of the added node. If not named, the node is renamed to its type, and if it shares name with a sibling, a number is suffixed more appropriately. This operation is very slow. As such, it is recommended leaving this to false, which assigns a dummy name featuring @ in both situations.
				If internal is different than , the child will be added as internal node. These nodes are ignored by methods like get_children, unless their parameter include_internal is true. It also prevents these nodes being duplicated with their parent. The intended usage is to hide the internal nodes from the user, so the user won't accidentally delete or modify them. Used by some GUI nodes, e.g. .
				Note: If node already has a parent, this method will fail. Use remove_child first to remove node from its current parent. For example:


				var child_node = get_child(0)
				if child_node.get_parent():
					child_node.get_parent().remove_child(child_node)
				add_child(child_node)


				Node childNode = GetChild(0);
				if (childNode.GetParent() != null)
				{
					childNode.GetParent().RemoveChild(childNode);
				}
				AddChild(childNode);


				If you need the child node to be added below a specific node in the list of children, use add_sibling instead of this method.
				Note: If you want a child to be persisted to a , you must set owner in addition to calling add_child. This is typically relevant for tool scripts and editor plugins. If add_child is called without setting owner, the newly added  will not be visible in the scene tree, though it will be visible in the 2D/3D view.

get_groups.description:
Returns an  of group names that the node has been added to.
				Note: To improve performance, the order of group names is not guaranteed and may vary between project runs. Therefore, do not rely on the group order.
				Note: This method may also return some group names starting with an underscore (_). These are internally used by the engine. To avoid conflicts, do not use custom groups starting with underscores. To exclude internal groups, see the following code snippet:


				# Stores the node's non-internal groups only (as an array of StringNames).
				var non_internal_groups = []
				for group in get_groups():
					if not str(group).begins_with("_"):
						non_internal_groups.push_back(group)


				// Stores the node's non-internal groups only (as a List of StringNames).
				List<string> nonInternalGroups = new List<string>();
				foreach (string group in GetGroups())
				{
					if (!group.BeginsWith("_"))
						nonInternalGroups.Add(group);
				}

can_process.description:
Returns true if the node can receive processing notifications and input callbacks (, _input, etc.) from the  and . The returned value depends on process_mode:
				- If set to , returns true when the game is processing, i.e. SceneTree.paused is false;
				- If set to , returns true when the game is paused, i.e. SceneTree.paused is true;
				- If set to , always returns true;
				- If set to , always returns false;
				- If set to , use the parent node's process_mode to determine the result.
				If the node is not inside the tree, returns false no matter the value of process_mode.

rpc_config.description:
Changes the RPC configuration for the given method. config should either be null to disable the feature (as by default), or a  containing the following entries:
				- rpc_mode: see ;
				- transfer_mode: see ;
				- call_local: if true, the method will also be called locally;
				- channel: an  representing the channel to send the RPC on.
				Note: In GDScript, this method corresponds to the  annotation, with various parameters passed (@rpc(any), @rpc(authority)...). See also the high-level multiplayer tutorial.

rotation.description:
Rotation of this node as Euler angles, in radians and in parent space (relative to the parent node). This value is obtained from basis's rotation.
			- The Vector3.x is the angle around the local X axis (pitch);
			- The Vector3.y is the angle around the local Y axis (yaw);
			- The Vector3.z is the angle around the local Z axis (roll).
			The order of each consecutive rotation can be changed with rotation_order (see  constants). By default, the YXZ convention is used ().
			Note: This property is edited in degrees in the inspector. If you want to use degrees in a script, use rotation_degrees.

global_rotation.description:
Global rotation of this node as Euler angles, in radians and in global space (relative to the world). This value is obtained from global_basis's rotation.
			- The Vector3.x is the angle around the global X axis (pitch);
			- The Vector3.y is the angle around the global Y axis (yaw);
			- The Vector3.z is the angle around the global Z axis (roll).
			Note: Unlike rotation, this property always follows the YXZ convention ().
			Note: If the node is not inside the tree, getting this property fails and returns .

get_cmdline_args.description:
Returns the command-line arguments passed to the engine, excluding arguments processed by the engine, such as --headless and --fullscreen.

				# Godot has been executed with the following command:
				# godot --headless --verbose --scene my_scene.tscn --custom
				OS.get_cmdline_args() # Returns ["--scene", "my_scene.tscn", "--custom"]

				Command-line arguments can be written in any form, including both --key value and --key=value forms so they can be properly parsed, as long as custom command-line arguments do not conflict with engine arguments.
				You can also incorporate environment variables using the get_environment method.
				You can set ProjectSettings.editor/run/main_run_args to define command-line arguments to be passed by the editor when running the project.
				Example: Parse command-line arguments into a  using the --key=value form for arguments:


				var arguments = {}
				for argument in OS.get_cmdline_args():
					if argument.contains("="):
						var key_value = argument.split("=")
						arguments.trim_prefix("--")] = key_value
					else:
						# Options without an argument will be present in the dictionary,
						# with the value set to an empty string.
						arguments = ""


				var arguments = new Dictionary<string, string>();
				foreach (var argument in OS.GetCmdlineArgs())
				{
					if (argument.Contains('='))
					{
						string[] keyValue = argument.Split("=");
						arguments.TrimPrefix("--")] = keyValue;
					}
					else
					{
						// Options without an argument will be present in the dictionary,
						// with the value set to an empty string.
						arguments = "";
					}
				}


				Note: Passing custom user arguments directly is not recommended, as the engine may discard or modify them. Instead, pass the standard UNIX double dash (--) and then the custom arguments, which the engine will ignore by design. These can be read via get_cmdline_user_args.

get_video_adapter_driver_info.description:
Returns the video adapter driver name and version for the user's currently active graphics card, as a . See also RenderingServer.get_video_adapter_api_version.
				The first element holds the driver name, such as nvidia, amdgpu, etc.
				The second element holds the driver version. For example, on the nvidia driver on a Linux/BSD platform, the version is in the format 510.85.02. For Windows, the driver's format is 31.0.15.1659.
				Note: This method is only supported on Linux/BSD and Windows when not running in headless mode. On other platforms, it returns an empty array.
				Note: This method will run slowly the first time it is called in a session; it can take several seconds depending on the operating system and hardware. It is blocking if called on the main thread, so it's recommended to call it on a separate thread using . This allows the engine to keep running while the information is being retrieved. However, get_video_adapter_driver_info is not thread-safe, so it should not be called from multiple threads at the same time.


				var thread = Thread.new()

				func _ready():
					thread.start(
						func():
							var driver_info = OS.get_video_adapter_driver_info()
							if not driver_info.is_empty():
								print("Driver: %s %s" % , driver_info])
							else:
								print("Driver: (unknown)")
					)

				func _exit_tree():
					thread.wait_to_finish()

set.description:
Assigns value to the given property. If the property does not exist or the given value's type doesn't match, nothing happens.


				var node = Node2D.new()
				node.set("global_scale", Vector2(8, 2.5))
				print(node.global_scale) # Prints (8.0, 2.5)


				var node = new Node2D();
				node.Set(Node2D.PropertyName.GlobalScale, new Vector2(8, 2.5f));
				GD.Print(node.GlobalScale); // Prints (8, 2.5)


				Note: In C#, property must be in snake_case when referring to built-in Godot properties. Prefer using the names exposed in the PropertyName class to avoid allocating a new  on each call.

get.description:
Returns the  value of the given property. If the property does not exist, this method returns null.


				var node = Node2D.new()
				node.rotation = 1.5
				var a = node.get("rotation") # a is 1.5


				var node = new Node2D();
				node.Rotation = 1.5f;
				var a = node.Get(Node2D.PropertyName.Rotation); // a is 1.5


				Note: In C#, property must be in snake_case when referring to built-in Godot properties. Prefer using the names exposed in the PropertyName class to avoid allocating a new  on each call.

set_indexed.description:
Assigns a new value to the property identified by the property_path. The path should be a  relative to this object, and can use the colon character (:) to access nested properties.


				var node = Node2D.new()
				node.set_indexed("position", Vector2(42, 0))
				node.set_indexed("position:y", -10)
				print(node.position) # Prints (42.0, -10.0)


				var node = new Node2D();
				node.SetIndexed("position", new Vector2(42, 0));
				node.SetIndexed("position:y", -10);
				GD.Print(node.Position); // Prints (42, -10)


				Note: In C#, property_path must be in snake_case when referring to built-in Godot properties. Prefer using the names exposed in the PropertyName class to avoid allocating a new  on each call.

get_indexed.description:
Gets the object's property indexed by the given property_path. The path should be a  relative to the current object and can use the colon character (:) to access nested properties.
				Examples: "position:x" or "material:next_pass:blend_mode".


				var node = Node2D.new()
				node.position = Vector2(5, -10)
				var a = node.get_indexed("position")   # a is Vector2(5, -10)
				var b = node.get_indexed("position:y") # b is -10


				var node = new Node2D();
				node.Position = new Vector2(5, -10);
				var a = node.GetIndexed("position");   // a is Vector2(5, -10)
				var b = node.GetIndexed("position:y"); // b is -10


				Note: In C#, property_path must be in snake_case when referring to built-in Godot properties. Prefer using the names exposed in the PropertyName class to avoid allocating a new  on each call.
				Note: This method does not support actual paths to nodes in the , only sub-property paths. In the context of nodes, use Node.get_node_and_resource instead.

get_property_list.description:
Returns the object's property list as an  of dictionaries. Each  contains the following entries:
				- name is the property's name, as a ;
				- class_name is an empty , unless the property is  and it inherits from a class;
				- type is the property's type, as an  (see );
				- hint is how the property is meant to be edited (see );
				- hint_string depends on the hint (see );
				- usage is a combination of .
				Note: In GDScript, all class members are treated as properties. In C# and GDExtension, it may be necessary to explicitly mark class members as Godot properties using decorators or attributes.

get_method_list.description:
Returns this object's methods and their signatures as an  of dictionaries. Each  contains the following entries:
				- name is the name of the method, as a ;
				- args is an  of dictionaries representing the arguments;
				- default_args is the default arguments as an  of variants;
				- flags is a combination of ;
				- id is the method's internal identifier ;
				- return is the returned value, as a ;
				Note: The dictionaries of args and return are formatted identically to the results of get_property_list, although not all entries are used.

notification.description:
Sends the given what notification to all classes inherited by the object, triggering calls to _notification, starting from the highest ancestor (the  class) and going down to the object's script.
				If reversed is true, the call order is reversed.


				var player = Node2D.new()
				player.set_script(load("res://player.gd"))

				player.notification(NOTIFICATION_ENTER_TREE)
				# The call order is Object -> Node -> Node2D -> player.gd.

				player.notification(NOTIFICATION_ENTER_TREE, true)
				# The call order is player.gd -> Node2D -> Node -> Object.


				var player = new Node2D();
				player.SetScript(GD.Load("res://player.gd"));

				player.Notification(NotificationEnterTree);
				// The call order is GodotObject -> Node -> Node2D -> player.gd.

				player.Notification(NotificationEnterTree, true);
				// The call order is player.gd -> Node2D -> Node -> GodotObject.

add_user_signal.description:
Adds a user-defined signal named signal. Optional arguments for the signal can be added as an  of dictionaries, each defining a name  and a type  (see ). See also has_user_signal and remove_user_signal.


				add_user_signal("hurt", [
					{ "name": "damage", "type": TYPE_INT },
					{ "name": "source", "type": TYPE_OBJECT }
				])


				AddUserSignal("Hurt",
				[
					new Godot.Collections.Dictionary()
					{
						{ "name", "damage" },
						{ "type", (int)Variant.Type.Int },
					},
					new Godot.Collections.Dictionary()
					{
						{ "name", "source" },
						{ "type", (int)Variant.Type.Object },
					},
				]);

call.description:
Calls the method on the object and returns the result. This method supports a variable number of arguments, so parameters can be passed as a comma separated list.


				var node = Node3D.new()
				node.call("rotate", Vector3(1.0, 0.0, 0.0), 1.571)


				var node = new Node3D();
				node.Call(Node3D.MethodName.Rotate, new Vector3(1f, 0f, 0f), 1.571f);


				Note: In C#, method must be in snake_case when referring to built-in Godot methods. Prefer using the names exposed in the MethodName class to avoid allocating a new  on each call.

set_deferred.description:
Assigns value to the given property, at the end of the current frame. This is equivalent to calling set through call_deferred.


				var node = Node2D.new()
				add_child(node)

				node.rotation = 1.5
				node.set_deferred("rotation", 3.0)
				print(node.rotation) # Prints 1.5

				await get_tree().process_frame
				print(node.rotation) # Prints 3.0


				var node = new Node2D();
				node.Rotation = 1.5f;
				node.SetDeferred(Node2D.PropertyName.Rotation, 3f);
				GD.Print(node.Rotation); // Prints 1.5

				await ToSignal(GetTree(), SceneTree.SignalName.ProcessFrame);
				GD.Print(node.Rotation); // Prints 3.0


				Note: In C#, property must be in snake_case when referring to built-in Godot properties. Prefer using the names exposed in the PropertyName class to avoid allocating a new  on each call.

callv.description:
Calls the method on the object and returns the result. Unlike call, this method expects all parameters to be contained inside arg_array.


				var node = Node3D.new()
				node.callv("rotate", )


				var node = new Node3D();
				node.Callv(Node3D.MethodName.Rotate, );


				Note: In C#, method must be in snake_case when referring to built-in Godot methods. Prefer using the names exposed in the MethodName class to avoid allocating a new  on each call.

